        wr_en <= 1'b0;
      end
      else begin
        if (enb) begin
          wr_en <= rdValid;
        end
      end
    end



  assign ramBus_wr_en = wr_en;

  assign ramBus_rd_addr = rdAddr;

  assign ramBus_rd_valid = rdValid;

endmodule  // clahe_ip_src_redistribute

